// Types for the bundled Quran data (generated by scripts/build-quran-data.mjs).

export interface SurahMeta {
  number: number;
  /** Arabic name, e.g. سُورَةُ ٱلْفَاتِحَةِ */
  name: string;
  englishName: string;
  englishNameTranslation: string;
  revelationType: 'Meccan' | 'Medinan';
  ayahCount: number;
  wordCount: number;
}

export interface Ayah {
  number: number;
  /** Hafs 'an 'Asim, Uthmani script (display) */
  text_uthmani: string;
  /** Imlaei/simplified orthography (ASR matching) */
  text_simple: string;
  juz: number;
  page: number;
  hizbQuarter: number;
  sajda: boolean;
  wordCount: number;
  /** true when the leading basmala was stripped from this (surah-opening) ayah */
  basmalaStripped: boolean;
}

export interface SurahData extends SurahMeta {
  ayahs: Ayah[];
}

export interface QuranIndex {
  surahs: SurahMeta[];
  ayahCount: number;
  wordCount: number;
}

export type AyahRef = { surah: number; ayah: number };
